function buildCondition(seed: GuideSeed): MSKCondition {
  return {
    slug: seed.slug, name: seed.name, region: seed.region, category: seed.category,
    evidenceLevel: seed.evidenceLevel, summary: seed.summary,
    involvedStructures: seed.structures, mechanism: seed.mechanism, classification: seed.classification,
    symptoms: seed.symptoms, signs: seed.signs, redFlags: seed.redFlags,
    tests: [{
      name: seed.test, purpose: seed.purpose, patientPosition: seed.setup,
      therapistPosition: "Position yourself to observe and stabilise the relevant segment without forcing the movement.",
      handPlacement: "Use comfortable, controlled contact appropriate to the test; avoid painful compression or excessive force.",
      procedure: ["Explain the test and obtain consent.", "Screen contraindications and compare sides when appropriate.", "Perform the movement slowly and apply only the required resistance or stress.", "Record familiar symptom reproduction, range, strength and side-to-side difference."],
      positive: seed.positive, interpretation: seed.interpretation,
      clinicalNote: "A special test modifies clinical probability; it does not confirm a diagnosis in isolation."
    }],
    differentials: seed.differentials, investigations: seed.investigations,
    treatmentPhases: [
      {phase:"Phase 1 — Protection, Education & Symptom-Guided Loading",goal:"Address safety, settle excessive irritability and maintain useful movement.",interventions:seed.phase1,exerciseDose:seed.dose1,progression:["Daily function is stable or improving.","No new red flags or progressive neurological deficit.","Exercise response returns to baseline by the following day."]},
      {phase:"Phase 2 — Mobility, Strength & Capacity",goal:"Restore the specific strength, mobility and control required by the condition.",interventions:seed.phase2,exerciseDose:seed.dose2,progression:["Target movement and resistance are tolerated with good quality.","Functional capacity is improving without sustained symptom flare.","Progression is based on objective performance and patient goals."]},
      {phase:"Phase 3 — Functional Restoration & Return to Activity",goal:"Rebuild real-world, occupational or sporting capacity.",interventions:seed.phase3,exerciseDose:seed.dose3,progression:["Condition-specific return criteria are met.","Full task exposure is completed progressively.","No clinically meaningful deterioration during the following 24 hours."]}
    ],
    manualTherapy:seed.manual, modalities:seed.modalities, returnCriteria:seed.returnCriteria,
    commonMistakes:seed.mistakes, clinicalPearls:seed.pearls, references:seed.reference
  };
}

export const expandedMSKConditions: MSKCondition[] = seeds.map(buildCondition);
